Item.method_code:
//Innovatorオブジェクト生成
var iomInv = aras.IomInnovator;
const relItemNames = ["h4_DATMaster DATFormat"];//帳票マスタのタブ名
const relItemNames_DATFormat = ["h4_DATFormatLink", "h4_DATFormat Doc","h4_DATFormat CLN","h4_DATFormat EXPCLN"];//開達書式のタブ名
const targetType = options.itemTypeName;
var targetIds = [];
var targetCategories = [];

//プロパティ入力画面を表示
try {
    
    // 表示するラベルを取得する。
    var dialog_title = aras.evalMethod(
 　 "h4_cmn_ShowMessage_Arg", 
 　 "", 
　  "h4_C_I_0001"
　);

    var dialog_msg = aras.evalMethod(
 　 "h4_cmn_ShowMessage_Arg", 
 　 "", 
　  "h4_C_I_0402"
　);
    
    //選択アイテムの取得
    var itemId = options.getState().grid.selectedRows[0];//選択アイテムが1つのときのみ実行される
    var selectedItem = iomInv.newItem(options.itemTypeName, "get");
    selectedItem.setID(itemId);
    selectedItem.setAttribute("select", "state,managed_by_id");
    selectedItem = selectedItem.apply();
    
    //プロパティ入力画面を表示
    window.ArasModules.Dialog.confirm(dialog_msg, { title: dialog_title }).then(function (result) {
        var errStr = "";
        if (result === 'ok') {
            // 無名async関数による非同期処理の即時実行
            (async (targetType) => {

                // 値設定ダイアログ生成
                var form = aras.getFormForDisplay(aras.getFormId('h4_DATMasterCopyInputInitVal'));
                var topWnd = top.aras.getMostTopWindowWithAras();
                var wnd = topWnd ? topWnd : window;

                // ⊿バージョンリスト取得
                var deltaVersionList = iomInv.newItem("List", "get");
                deltaVersionList.setProperty("name", "h4_DeltaVersion");
                deltaVersionList = deltaVersionList.apply();
                var listValues = iomInv.newItem("Value", "get");
                listValues.setAttribute("select", "label,value");
                listValues.setProperty("source_id", deltaVersionList.getID());
                listValues = listValues.apply();
                var deltaVersion = [];
                var deltaVersionLabel = [];

                for (var i = 0; i < listValues.getItemCount(); i++) {
                    deltaVersion.push(listValues.getItemByIndex(i).getProperty("value"));
                    deltaVersionLabel.push(listValues.getItemByIndex(i).getProperty("label"));
                }

                var params = {
                    title: "帳票マスタ作成時の値設定",
                    formId: form.node.getAttribute('id'),
                    aras: aras,
                    deltaVersion: deltaVersion,
                    label: deltaVersionLabel,
                    dialogWidth: 600,
                    dialogHeight: 300,
                    content: 'ShowFormAsADialog.html'
                };

                topWnd.ArasModules.MaximazableDialog.show('iframe', params).promise.then(function (dlgRes) {
                    if (!dlgRes) {
                        //閉じるボタン
                        aras.browserHelper.toggleSpinner(parent.document, false);
                        return;
                    }

                    //初期値入力ダイアログの結果を取得（0:⊿バージョン, 1 :名称）
                    var results = dlgRes.split(',');

                    //帳票マスタ複製
                    var grid = options.getState().grid;
                    var rowCount = 0;
                    if (grid != null) {
                        rowCount = grid.selectedRows.length;
                    }
                    
                    //メソッド「h4_DATMaster_Copy」を呼び出し帳票マスタをコピーする
                    var result = iomInv.newItem("Method", "h4_DATMaster_Copy");
                    result.setProperty("id", itemId);
                    result.setProperty("deltaVersion", results[0]);
                    result.setProperty("name", results[1]);
                    result.setProperty("type", targetType);
                    result = result.apply();

                    // //コピーしたアイテムを表示
                    var newWindow = aras.uiShowItem(options.itemTypeName, result.getID());

                });
            })(targetType);
        }
    });
    
}
catch (e) 
{
    var error_msg = aras.evalMethod(
 　 "h4_cmn_ShowMessage_Arg", 
 　 "", 
　  "h4_C_E_0002"
　);
　
　aras.AlertError(error_msg);
　
}

return;
